import{_ as a}from"./chunks/settings-cal.pc.ko.DNqctmh_.js";import{_ as o,o as r,c as e,a5 as n}from"./chunks/framework.BjM_ivYE.js";const p=JSON.parse('{"title":"캘리브레이션 & 튜닝","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/troubleshooting/calibration-tuning.md","filePath":"ko/manual/troubleshooting/calibration-tuning.md","lastUpdated":1789720001000}'),l={name:"ko/manual/troubleshooting/calibration-tuning.md"};function s(i,t,d,h,m,g){return r(),e("div",null,[...t[0]||(t[0]=[n('<h1 id="캘리브레이션-튜닝" tabindex="-1">캘리브레이션 &amp; 튜닝 <a class="header-anchor" href="#캘리브레이션-튜닝" aria-label="Permalink to &quot;캘리브레이션 &amp; 튜닝&quot;">​</a></h1><p>로봇의 보행 안정성을 위한 보정은 앱의 <strong>로봇 설정 → 캘리브레이션</strong>에 모여 있습니다.</p><p><img src="'+a+'" alt="로봇 설정 → 캘리브레이션"></p><h2 id="무게-중심-보정-zmp" tabindex="-1">무게 중심 보정 (ZMP) <a class="header-anchor" href="#무게-중심-보정-zmp" aria-label="Permalink to &quot;무게 중심 보정 (ZMP)&quot;">​</a></h2><p>ZMP(Zero Moment Point) 보정은 <strong>서 있는 자세에서 무게중심 오프셋을 자동으로 찾는</strong> 작업입니다. 적재물을 바꿨거나 보행이 한쪽으로 치우칠 때 실행합니다.</p><h3 id="사전-준비" tabindex="-1">사전 준비 <a class="header-anchor" href="#사전-준비" aria-label="Permalink to &quot;사전 준비&quot;">​</a></h3><ul><li>로봇을 <strong>평평하고 단단한 바닥</strong>에 두세요.</li><li>로봇이 <strong>한 걸음 걸을 수 있는 공간</strong>을 비워 두세요 — 보정 전에 다리를 정렬하는 걸음을 내딛습니다.</li><li>앱이 로봇에 연결되어 있어야 합니다.</li><li><strong>로봇이 서 있어야 합니다.</strong> 앉아 있거나 제어가 꺼진 상태에서는 시작할 수 없습니다.</li></ul><h3 id="진행-순서" tabindex="-1">진행 순서 <a class="header-anchor" href="#진행-순서" aria-label="Permalink to &quot;진행 순서&quot;">​</a></h3><ol><li>앱에서 <strong>로봇 설정 → 캘리브레이션</strong>을 엽니다.</li><li><strong>무게 중심 보정</strong> 절의 <code>무게 중심 오프셋 자동 보정</code>을 누릅니다. 실행할 수 없는 상태면 버튼이 잠기고 <strong>이유가 그 자리에 표시</strong>됩니다 (예: <em>서 있어야 합니다 — 앉음·제어 꺼짐 상태에서는 무게 중심 보정을 시작할 수 없습니다</em>).</li><li>확인 창에서 실행을 확정합니다.</li><li>로봇이 <strong>한 걸음 천천히 걸어 다리를 가지런히 놓은 뒤</strong> 자동 보정에 들어갑니다. 진행 창에 <em>무게중심 보정중입니다</em> 가 표시되며, <strong>최대 60초</strong> 걸립니다.</li><li>수렴하면 로봇이 <strong>스스로 값을 저장하고 STAND 로 돌아옵니다.</strong> 창에 <em>무게중심 보정이 완료되었습니다</em> 가 뜨고 2초 뒤 닫힙니다.</li><li>로봇을 움직여 보며 동작이 정상인지 확인합니다.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">주의</p><p>보정이 끝날 때까지 <strong>로봇을 건드리지 마세요.</strong> 로봇 위에 물건을 올리거나 밀면 보정이 어긋납니다. 창을 닫아도 로봇의 보정은 계속 진행됩니다.</p></div></div><h3 id="실패했을-때" tabindex="-1">실패했을 때 <a class="header-anchor" href="#실패했을-때" aria-label="Permalink to &quot;실패했을 때&quot;">​</a></h3><p>실패해도 <strong>이전 보정값은 그대로 유지됩니다.</strong> 창에 표시되는 사유에 따라 조치하세요.</p><table tabindex="0"><thead><tr><th>화면에 나오는 말</th><th>조치</th></tr></thead><tbody><tr><td><em>로봇이 서 있어야 합니다.</em></td><td>STAND 로 바꾼 뒤 다시 실행합니다</td></tr><tr><td><em>로봇이 완전히 멈춘 뒤 다시 실행하세요.</em></td><td>보행·회전이 멈출 때까지 기다립니다</td></tr><tr><td><em>로봇을 평지에 위치시켜 주십시오.</em></td><td>기울어진 곳입니다. 평평한 바닥으로 옮깁니다</td></tr><tr><td><em>다리 정렬 걸음이 끝나지 않았습니다.</em></td><td>한 걸음 걸을 공간을 확보하고 다시 실행합니다</td></tr><tr><td><em>60초 안에 수렴하지 못했습니다.</em></td><td>바닥이 무르거나 미끄럽지 않은지 확인하고 다시 실행합니다</td></tr><tr><td><em>로봇이 응답하지 않습니다.</em></td><td><a href="/RBQ/ko/manual/gui/connection.html">연결</a>을 확인합니다</td></tr></tbody></table><p>실패 사유는 시스템 로그에도 남습니다 — <a href="/RBQ/ko/manual/gui/logs.html">로그</a>에서 확인할 수 있습니다.</p><h2 id="함께-확인할-것" tabindex="-1">함께 확인할 것 <a class="header-anchor" href="#함께-확인할-것" aria-label="Permalink to &quot;함께 확인할 것&quot;">​</a></h2><ul><li>적재물을 바꿨다면 <strong>먼저 <a href="/RBQ/ko/manual/troubleshooting/payload_setting.html">페이로드 설정</a>을 갱신</strong>한 뒤 무게 중심 보정을 하세요. 순서가 바뀌면 보정값이 옛 하중 기준으로 남습니다.</li><li>같은 화면의 <strong>IMU 영점</strong>, <strong>다리 홈포즈(치구)</strong>, <strong>카메라</strong>, <strong>도킹</strong> 보정은 <a href="/RBQ/ko/manual/gui/settings.html">설정</a>에 정리되어 있습니다.</li></ul><h2 id="still-stuck" tabindex="-1">그래도 해결되지 않으면 <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;그래도 해결되지 않으면 {#still-stuck}&quot;">​</a></h2><p>실패한 보정 이름과 화면에 나온 사유, 그리고 그때 실린 적재물을 함께 알려주시면 확인이 빠릅니다.</p><p><strong>→ <a href="/RBQ/ko/manual/support/">기술지원 요청</a></strong></p>',19)])])}const b=o(l,[["render",s]]);export{p as __pageData,b as default};
